	private static final PlanLifecycleStore.ObjectiveEnvelope ENVELOPE = new PlanLifecycleStore.ObjectiveEnvelope(
			50.0d, 60.0d, 70.0d);
	private static final PatternKey PATTERN = new PatternKey(P1, 1);
	private static final int LOGICAL = RuntimeFeedbackContract.ADMIT_LOGICAL;
