	@Test
	void aModelValueWithinTheToleranceIsServedOnlyWhenNotBitExactAndBeyondItIsAChange(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("moves");
		teach(stats, key, 40, 7L);
		FrontierLearningModel.DimensionEstimate recorded = logicalRead(stats, key).estimate();
		assertNotNull(recorded, "COVERAGE_PREREQUISITE: an estimate is recorded");
		LmdbPlanningReadLog.Log log = record(() -> logicalRead(stats, key));

		teach(stats, key, 1, 7L);
		FrontierLearningModel.DimensionEstimate nudged = logicalRead(stats, key).estimate();
		assertNotEquals(recorded, nudged, "COVERAGE_PREREQUISITE: one more observation moves the estimate");
		LmdbPlanningReadLog.ReplayResult withinTolerance = log.replayAgainstOwners(TOLERANCE, () -> {
		});
		LmdbPlanningReadLog.ReplayResult bitExact = log.replayAgainstOwners(0.0d, () -> {
		});

		teach(stats, key, 64, 7_000L);
		LmdbPlanningReadLog.ReplayResult beyond = log.replayAgainstOwners(TOLERANCE, () -> {
		});

		assertAll(
				() -> assertEquals(LmdbPlanningReadLog.Verdict.WITHIN_TOLERANCE, withinTolerance.verdict(),
						"a value that moved within the tolerance is served: " + withinTolerance),
				() -> assertChanged(bitExact, LmdbPlanningReadLog.LOGICAL, 0),
				() -> assertChanged(beyond, LmdbPlanningReadLog.LOGICAL, 0));
	}

	@Test
	void cumulativeDriftInStepsWithinTheToleranceEndsAsAChange(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("drift");
		teach(stats, key, 40, 7L);
		LmdbPlanningReadLog.Log log = record(() -> logicalRead(stats, key));

		FrontierLearningModel.DimensionEstimate previous = logicalRead(stats, key).estimate();
		boolean servedWithinTolerance = false;
		LmdbPlanningReadLog.ReplayResult last = null;
		double rows = 7.0d;
		for (int step = 0; step < 400; step++) {
			rows *= 1.05d;
			teach(stats, key, 1, Math.round(rows));
			FrontierLearningModel.DimensionEstimate current = logicalRead(stats, key).estimate();
			assertNotNull(current, "COVERAGE_PREREQUISITE: the estimate stays present");
			assertTrue(logDistance(previous, current) <= TOLERANCE,
					"COVERAGE_PREREQUISITE: every step moves the value within the tolerance");
			previous = current;
			last = log.replayAgainstOwners(TOLERANCE, () -> {
			});
			if (last.verdict() == LmdbPlanningReadLog.Verdict.WITHIN_TOLERANCE) {
				servedWithinTolerance = true;
			} else if (last.verdict() != LmdbPlanningReadLog.Verdict.IDENTICAL) {
				break;
			}
		}
		boolean served = servedWithinTolerance;
		LmdbPlanningReadLog.ReplayResult end = last;
		assertAll(
				() -> assertTrue(served, "COVERAGE_PREREQUISITE: an early step is served within the tolerance"),
				() -> assertChanged(end, LmdbPlanningReadLog.LOGICAL, 0));
	}

