	@Test
	void aTypedPublicationDecayingAHeldLegacyPosteriorAdvancesItsVersion() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningKey legacy = FrontierLearningKey.of("join", "identity", 1L, 2L, "none", "none", "none");
		model.observe(legacy, FrontierCostDimension.OUTPUT_ROWS, 10.0d, 20.0d, 1L);
		FrontierLearningModel.DimensionEstimate before = model.estimate(legacy, FrontierCostDimension.OUTPUT_ROWS,
				10.0d);
		long version = model.legacyPosteriorMutations();
		LogicalLearningKey key = logical("typed-publication");
		RuntimeFeedbackContract contract = contract(key, APPLICABILITY, ROWS_ONLY, LOGICAL);
		FrontierLearningModel.ResolvedCells cells = model.resolve(key, PHYSICAL, APPLICABILITY, true, false);
		boolean[] admitted = new boolean[1];
		RuntimeFeedbackAccumulator target = new RuntimeFeedbackAccumulator(contract,
				new RuntimeFeedbackAccumulator.Destination() {
					@Override
					public void publish(InvocationAggregateView observation) {
						admitted[0] = model.observeResolved(cells, contract, observation, 5L);
					}

					@Override
					public void release() {
						model.release(cells);
					}
				});
		target.open();
		target.close(7L, 7.0d, 7L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, TerminationClassification.EXHAUSTED);
		target.publish(true);

		assertAll(
				() -> assertTrue(admitted[0], "COVERAGE_PREREQUISITE: the typed observation is admitted"),
				() -> assertNotEquals(before, model.estimate(legacy, FrontierCostDimension.OUTPUT_ROWS, 10.0d),
						"COVERAGE_PREREQUISITE: the decay clock it moved changes the legacy read"),
				() -> assertTrue(model.legacyPosteriorMutations() > version,
						"a typed publication that decays a held legacy posterior advances its version"));
	}

