	@Test
	void anExactFactThatBecomesCurrentOrChangesRowsIsAChangeAndAnIdenticalRewriteIsNot(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("fact");
		LmdbPlanningReadLog.Log absent = record(() -> stats.exactCardinalityFact(key, APPLICABILITY));
		publish(stats, contract(key, APPLICABILITY, ROWS_ONLY, EXACT_FACT), 7L, 7.0d);
		LmdbPlanningReadLog.ReplayResult becameCurrent = absent.replayAgainstOwners(TOLERANCE, () -> {
		});

		LmdbPlanningReadLog.Log seven = record(() -> stats.exactCardinalityFact(key, APPLICABILITY));
		publish(stats, contract(key, APPLICABILITY, ROWS_ONLY, EXACT_FACT), 7L, 7.0d);
		LmdbPlanningReadLog.ReplayResult rewritten = seven.replayAgainstOwners(0.0d, () -> {
		});
		publish(stats, contract(key, APPLICABILITY, ROWS_ONLY, EXACT_FACT), 8L, 8.0d);
		LmdbPlanningReadLog.ReplayResult rowsChanged = seven.replayAgainstOwners(TOLERANCE, () -> {
		});

		assertAll(
				() -> assertEquals(8.0d, stats.exactCardinalityFact(key, APPLICABILITY), 0.0d,
						"COVERAGE_PREREQUISITE: the fact moved"),
				() -> assertChanged(becameCurrent, LmdbPlanningReadLog.EXACT_FACT, 0),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, rewritten.verdict()),
				() -> assertChanged(rowsChanged, LmdbPlanningReadLog.EXACT_FACT, 0));
	}

	// ---------------------------------------------------------------- lifecycle

	@Test
	void aComparedLifecycleFieldChangeIsAChangeButARegressionLimitAloneIsNot(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("lifecycle");
		PlanLifecycleStore.Decision recorded = lifecycleRead(stats, key, PHYSICAL, ENVELOPE);
		// Rule 3': a monitoring lifecycle read is a keyless guard; full keys keep the keyed comparison pinned here.
		String previous = System.setProperty(LmdbPlanningReadLog.FULL_KEYS_PROPERTY, "true");
		LmdbPlanningReadLog.Log log;
		try {
			log = record(() -> lifecycleRead(stats, key, PHYSICAL, ENVELOPE));
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbPlanningReadLog.FULL_KEYS_PROPERTY);
			} else {
				System.setProperty(LmdbPlanningReadLog.FULL_KEYS_PROPERTY, previous);
			}
		}

		// A sibling alternative's decision overwrites its own planned envelope: only the regression limit moves.
		lifecycleRead(stats, key, SIBLING, new PlanLifecycleStore.ObjectiveEnvelope(100.0d, 100.0d, 100.0d));
		PlanLifecycleStore.Decision siblingMoved = stats.peekPlanLifecycleDecision(key, PHYSICAL, APPLICABILITY,
				ENVELOPE);
		LmdbPlanningReadLog.ReplayResult limitOnly = log.replayAgainstOwners(0.0d, () -> {
		});

		publish(stats, lifecycleContract(key), 6L, 60.0d);
		LmdbPlanningReadLog.ReplayResult promoted = log.replayAgainstOwners(TOLERANCE, () -> {
		});

		assertAll(
				() -> assertNotEquals(recorded.regressionLimit(), siblingMoved.regressionLimit(),
						"COVERAGE_PREREQUISITE: the regression limit moved"),
				() -> assertEquals(recorded.eligible(), siblingMoved.eligible()),
				() -> assertEquals(recorded.lastGood(), siblingMoved.lastGood()),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, limitOnly.verdict(),
						"the regression limit depends on the order of decisions and is not compared"),
				() -> assertTrue(stats.peekPlanLifecycleDecision(key, PHYSICAL, APPLICABILITY, ENVELOPE).lastGood(),
						"COVERAGE_PREREQUISITE: the observation verified the alternative as last good"),
				() -> assertChanged(promoted, LmdbPlanningReadLog.LIFECYCLE, 0));
	}

	@Test
	void everyComparedLifecycleFieldIsComparedAndNothingElse(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("compared-fields");
		PlanLifecycleStore.Decision current = lifecycleRead(stats, key, PHYSICAL, ENVELOPE);
		assertTrue(current.eligible() && !current.lastGood(), "COVERAGE_PREREQUISITE: a fresh monitored entry");

		LmdbPlanningReadLog.ReplayResult same = lifecycleLog(stats, key, current).replayAgainstOwners(0.0d, () -> {
		});
		LmdbPlanningReadLog.ReplayResult textOnly = lifecycleLog(stats, key, new PlanLifecycleStore.Decision(
				PlanLifecycleStore.State.APPLYING, current.eligible(), current.lastGood(), current.comparisonCost(),
				ENVELOPE, "other-digest", 1.0d, 2.0d, "other-reason")).replayAgainstOwners(0.0d, () -> {
				});
		LmdbPlanningReadLog.ReplayResult eligible = lifecycleLog(stats, key, new PlanLifecycleStore.Decision(
				current.state(), !current.eligible(), current.lastGood(), current.comparisonCost(), ENVELOPE,
				current.lastGoodPhysicalDigest(), current.lastGoodVerifiedUpper(), current.regressionLimit(),
				current.reason())).replayAgainstOwners(0.0d, () -> {
				});
		LmdbPlanningReadLog.ReplayResult lastGood = lifecycleLog(stats, key, new PlanLifecycleStore.Decision(
				current.state(), current.eligible(), !current.lastGood(), current.comparisonCost(), ENVELOPE,
				current.lastGoodPhysicalDigest(), current.lastGoodVerifiedUpper(), current.regressionLimit(),
				current.reason())).replayAgainstOwners(0.0d, () -> {
				});
		LmdbPlanningReadLog.ReplayResult cost = lifecycleLog(stats, key, new PlanLifecycleStore.Decision(
				current.state(), current.eligible(), current.lastGood(), current.comparisonCost() + 1.0d, ENVELOPE,
				current.lastGoodPhysicalDigest(), current.lastGoodVerifiedUpper(), current.regressionLimit(),
				current.reason())).replayAgainstOwners(TOLERANCE, () -> {
				});

		assertAll(
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, same.verdict(), same.toString()),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, textOnly.verdict(),
						"state, reason, digests, verified upper and regression limit are not compared"),
				() -> assertChanged(eligible, LmdbPlanningReadLog.LIFECYCLE, 0),
				() -> assertChanged(lastGood, LmdbPlanningReadLog.LIFECYCLE, 0),
				() -> assertChanged(cost, LmdbPlanningReadLog.LIFECYCLE, 0));
	}

	private static LmdbPlanningReadLog.Log lifecycleLog(LmdbOperatorFeedbackStats stats, LogicalLearningKey key,
			PlanLifecycleStore.Decision decision) {
		return record(
				() -> LmdbPlanningReadLog.lifecycle(stats, key, PHYSICAL, APPLICABILITY, ENVELOPE, decision, true));
	}

	@Test
	void theLifecyclePeekOfAnAbsentEntryAnswersAsAFreshAdmissionWithoutAdmitting(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("absent-lifecycle");
		LmdbOperatorFeedbackStats other = feedback(directory.resolve("other"));
		// The other provider decides the same key once: what this provider would answer for a fresh admission.
		PlanLifecycleStore.Decision fresh = lifecycleRead(other, key, PHYSICAL, ENVELOPE);
		LmdbPlanningReadLog.Log log = record(() -> LmdbPlanningReadLog.lifecycle(stats, key, PHYSICAL,
				APPLICABILITY, ENVELOPE, fresh, true));
		long revision = stats.planLifecycleRevision();
		long inputs = stats.planLifecycleDecisionInputVersion();
		long planning = stats.planningRevision();

		LmdbPlanningReadLog.ReplayResult result = log.replayAgainstOwners(0.0d, () -> {
		});

		assertAll(
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, result.verdict(), result.toString()),
				() -> assertEquals(revision, stats.planLifecycleRevision(), "no admission or transition"),
				() -> assertEquals(inputs, stats.planLifecycleDecisionInputVersion(),
						"no admission, eviction or planned-envelope overwrite"),
				() -> assertEquals(planning, stats.planningRevision()));
	}

