	@Test
	void aLearnedFilterSurfaceThatAppearsIsAChange(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		Filter filter = filter("surface");
		LmdbPlanningReadLog.Log log = record(() -> filters.estimateLearnedSurface(filter));

		filters.recordFilterOutcome(filter, 1L, 3L);
		LmdbPlanningReadLog.Log learnedOnce = record(() -> filters.estimateLearnedSurface(filter));
		LmdbPlanningReadLog.ReplayResult appeared = log.replayAgainstOwners(TOLERANCE, () -> {
		});
		// The same pass ratio over more evidence: a different confidence and interval, so a different outcome.
		filters.recordFilterOutcome(filter, 1L, 3L);

		assertAll(
				() -> assertNotNull(filters.estimateLearnedSurface(filter),
						"COVERAGE_PREREQUISITE: the surface was learned"),
				() -> assertChanged(appeared, LmdbPlanningReadLog.LEARNED_SURFACE, 0),
				() -> assertChanged(learnedOnce.replayAgainstOwners(TOLERANCE, () -> {
				}), LmdbPlanningReadLog.LEARNED_SURFACE, 0));
	}

	/** R14: a pass ratio feeds structural thresholds, so it compares bit-exact whatever the tolerance. */
	@Test
	void aPassRatioThatMovesAtAllIsAChangeAndZeroEqualsOnlyZero(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		filters.recordFilterOutcome(PATTERN, "half", 50L, 50L);
		filters.recordFilterOutcome(PATTERN, "zero", 0L, 10L);
		LmdbPlanningReadLog.Log half = record(() -> filters.getFilterPassRatio(PATTERN, "half"));
		LmdbPlanningReadLog.Log zero = record(() -> filters.getFilterPassRatio(PATTERN, "zero"));
		LmdbPlanningReadLog.Log count = record(() -> filters.getFilterObservationCount(PATTERN, "half"));

		filters.recordFilterOutcome(PATTERN, "half", 1L, 0L);
		filters.recordFilterOutcome(PATTERN, "zero", 1L, 0L);
		double nudged = filters.getFilterPassRatio(PATTERN, "half");
		LmdbPlanningReadLog.ReplayResult within = half.replayAgainstOwners(TOLERANCE, () -> {
		});
		LmdbPlanningReadLog.ReplayResult bitExact = half.replayAgainstOwners(0.0d, () -> {
		});
		LmdbPlanningReadLog.ReplayResult fromZero = zero.replayAgainstOwners(Math.log(1000.0d), () -> {
		});
		LmdbPlanningReadLog.ReplayResult countMoved = count.replayAgainstOwners(Math.log(1000.0d), () -> {
		});
		filters.recordFilterOutcome(PATTERN, "half", 400L, 0L);
		LmdbPlanningReadLog.ReplayResult beyond = half.replayAgainstOwners(TOLERANCE, () -> {
		});

		assertAll(
				() -> assertTrue(nudged != 0.5d && Math.abs(Math.log(nudged) - Math.log(0.5d)) <= TOLERANCE,
						"COVERAGE_PREREQUISITE: the first nudge stays within the tolerance: " + nudged),
				() -> assertChanged(within, LmdbPlanningReadLog.FILTER_RATIO, 0),
				() -> assertChanged(bitExact, LmdbPlanningReadLog.FILTER_RATIO, 0),
				() -> assertChanged(fromZero, LmdbPlanningReadLog.FILTER_RATIO, 0),
				() -> assertChanged(countMoved, LmdbPlanningReadLog.FILTER_COUNT, 0),
				() -> assertChanged(beyond, LmdbPlanningReadLog.FILTER_RATIO, 0));
	}

	@Test
	void everyLearnedFilterReadIsRecordedAtItsOwner(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		Filter filter = rangeFilter();
		StatementPattern pattern = (StatementPattern) filter.getArg();
		LmdbPlanningReadLog.Log log = record(() -> {
			filters.estimateLearnedSurface(filter);
			filters.getFilterPassRatio(PATTERN, "f");
			filters.getFilterTemplatePassRatio(PATTERN, "t");
			filters.getPatternPassRatio(PATTERN);
			filters.getFilterObservationCount(PATTERN, "f");
			filters.getFilterTemplateObservationCount(PATTERN, "t");
			filters.getPatternObservationCount(PATTERN);
			filters.estimateCachedFilterPass(filter, pattern);
		});

		assertAll(
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.LEARNED_SURFACE)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.FILTER_RATIO)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.TEMPLATE_RATIO)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.PATTERN_RATIO)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.FILTER_COUNT)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.TEMPLATE_COUNT)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.PATTERN_COUNT)),
				() -> assertEquals(1, log.count(LmdbPlanningReadLog.SAMPLE)),
				() -> assertEquals(8, log.readCount()));
	}

	@Test
	void aFilterReadMadeWhileTheProviderWithheldItsStateIsAChangeOnceItIsAvailableAgain(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		Filter filter = rangeFilter();
		filters.setLearnedStateObserver(new LmdbFilterSelectivityStats.LearnedStateObserver() {
			@Override
			public void learnedStateReset() {
				throw new IllegalStateException("injected reset failure");
			}
		});
		try {
			filters.reset();
		} catch (IllegalStateException expected) {
			// The failed reset withholds the learned state until a reset completes.
		}
		assertFalse(filters.learnedEvidenceAvailable(), "COVERAGE_PREREQUISITE: the state is withheld");
		LmdbPlanningReadLog.Log log = record(() -> {
			filters.estimateLearnedSurface(filter);
			filters.estimateCachedFilterPass(filter, (StatementPattern) filter.getArg());
		});
		LmdbPlanningReadLog.ReplayResult whileWithheld = log.replayAgainstOwners(0.0d, () -> {
		});

		filters.setLearnedStateObserver(null);
		filters.reset();

		assertAll(
				() -> assertEquals(2, log.readCount()),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, whileWithheld.verdict()),
				() -> assertTrue(filters.learnedEvidenceAvailable(), "COVERAGE_PREREQUISITE: available again"),
				() -> assertChanged(log.replayAgainstOwners(TOLERANCE, () -> {
				}), LmdbPlanningReadLog.LEARNED_SURFACE, 0));
	}

