	@Test
	void legacyEstimateStateChangesMatterOnlyToPlanningsThatUsedTheLegacyEstimate(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		Join observed = join();
		complete(observed, 100L, 10.0d, 20.0d);
		observed.setJoinLeftBindingsConsumedActual(50L);
		observed.setJoinRightBindingsConsumedActual(100L);
		stats.recordOperatorOutcome(observed);
		LmdbPlanningReadLog.Log used = record(() -> assertNotNull(stats.estimate(join(), 200.0d, 100.0d, 10.0d,
				20.0d), "COVERAGE_PREREQUISITE: the legacy operator reader has evidence"));
		LmdbPlanningReadLog.Log unused = record(() -> logicalRead(stats, logical("unused")));

		Join again = join();
		complete(again, 300L, 10.0d, 20.0d);
		again.setJoinLeftBindingsConsumedActual(50L);
		again.setJoinRightBindingsConsumedActual(300L);
		stats.recordOperatorOutcome(again);

		assertAll(
				() -> assertChanged(used.replayAgainstOwners(TOLERANCE, () -> {
				}), LmdbPlanningReadLog.LEGACY_GUARD, 0),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, unused.replayAgainstOwners(0.0d, () -> {
				}).verdict()));
	}

