	@Test
	void aTypedObservationDecayingAHeldLegacyPosteriorAdvancesTheLegacyPosteriorVersion() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningKey legacy = FrontierLearningKey.of("join", "identity", 1L, 2L, "none", "none", "none");
		long empty = model.legacyPosteriorMutations();
		model.observeLogical(logical("typed-only"), APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, ROWS_ONLY,
				7.0d, 1L);
		long typedWhileEmpty = model.legacyPosteriorMutations();
		model.observe(legacy, FrontierCostDimension.OUTPUT_ROWS, 10.0d, 20.0d, 2L);
		long afterLegacy = model.legacyPosteriorMutations();
		FrontierLearningModel.DimensionEstimate before = model.estimate(legacy, FrontierCostDimension.OUTPUT_ROWS,
				10.0d);
		model.observeLogical(logical("typed-only"), APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, ROWS_ONLY,
				7.0d, 3L);
		FrontierLearningModel.DimensionEstimate after = model.estimate(legacy, FrontierCostDimension.OUTPUT_ROWS,
				10.0d);

		assertAll(
				() -> assertEquals(empty, typedWhileEmpty,
						"a typed observation while no legacy posterior is held changes no legacy read"),
				() -> assertTrue(afterLegacy > typedWhileEmpty, "a legacy observation is a legacy posterior change"),
				() -> assertNotEquals(before, after,
						"COVERAGE_PREREQUISITE: the decay clock the typed observation moved changes the legacy read"),
				() -> assertTrue(model.legacyPosteriorMutations() > afterLegacy,
						"a typed observation that decays a held legacy posterior must advance its version"));
	}

	@Test
	void theLegacyPlanningVersionMovesWithTheLegacyClockButNotWithATypedAdmission(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		long initial = stats.legacyPlanningVersion();
		teach(stats, logical("typed"), 1, 7L);
		long afterTyped = stats.legacyPlanningVersion();
		Join observed = join();
		complete(observed, 100L, 10.0d, 20.0d);
		stats.recordOperatorOutcome(observed);

		assertAll(
				() -> assertEquals(initial, afterTyped,
						"a typed admission while no legacy state is held is invisible to the legacy readers"),
				() -> assertTrue(stats.legacyPlanningVersion() > afterTyped,
						"a legacy-path observation is a legacy change"));
	}

